 "content": "def transform(grid):
    """Compact each horizontal object to a cell, listing 3-objects then 2-objects."""
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {3: 0, 2: 0}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in counts or (r, c) in seen:
                continue
            # Count each 4-connected object once.
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            counts[color] += 1
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]

